-- Упражнения книги 19, глава 7 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 7, 'la7-lsns-report', 0, 'func', 'Сводка lsns по типам', 'Вход — вывод lsns без аргументов: колонки NS TYPE NPROCS PID USER COMMAND, первая строка заголовок. Поле COMMAND может содержать пробелы. Напишите функцию lsns_report(text): верните список кортежей (type, число_строк, сумма_NPROCS), по одному на каждый встретившийся тип, отсортированный по имени типа. Пустые строки и заголовок пропускайте; пустой вывод даёт [].', 'def lsns_report(text):
    pass
', 'line.split(None, 5) оставляет COMMAND целиком; строка данных начинается с числа.', '{"func": "lsns_report", "tests": [{"args": ["        NS TYPE   NPROCS   PID USER   COMMAND\n4026531834 time      212     1 root   /sbin/init\n4026531835 cgroup    212     1 root   /sbin/init\n4026531836 pid       210     1 root   /sbin/init\n4026531837 user      212     1 root   /sbin/init\n4026531838 uts       209     1 root   /sbin/init\n4026531839 ipc       209     1 root   /sbin/init\n4026531840 net       209     1 root   /sbin/init\n4026531841 mnt       205     1 root   /sbin/init\n4026532198 mnt         1   402 root   /lib/systemd/systemd-udevd\n4026532512 mnt         2  3801 root   nginx: master process nginx -g daemon off;\n4026532513 uts         2  3801 root   nginx: master process nginx -g daemon off;\n4026532514 ipc         2  3801 root   nginx: master process nginx -g daemon off;\n4026532515 pid         2  3801 root   nginx: master process nginx -g daemon off;\n4026532516 cgroup      2  3801 root   nginx: master process nginx -g daemon off;\n4026532517 net         2  3801 root   nginx: master process nginx -g daemon off;\n"], "expected": [{"__tuple__": ["cgroup", 2, 214]}, {"__tuple__": ["ipc", 2, 211]}, {"__tuple__": ["mnt", 3, 208]}, {"__tuple__": ["net", 2, 211]}, {"__tuple__": ["pid", 2, 212]}, {"__tuple__": ["time", 1, 212]}, {"__tuple__": ["user", 1, 212]}, {"__tuple__": ["uts", 2, 211]}]}, {"args": ["        NS TYPE NPROCS PID USER COMMAND\n4026531840 net       5   1 root /sbin/init\n"], "expected": [{"__tuple__": ["net", 1, 5]}]}, {"args": [""], "expected": []}, {"args": ["        NS TYPE   NPROCS   PID USER   COMMAND\n"], "expected": []}, {"args": ["        NS TYPE   NPROCS   PID USER    COMMAND\n4026531837 user       40     1 root    /usr/lib/systemd/systemd --switched-root --system\n4026532601 user        3  7710 alice   /usr/bin/podman run --rm busybox sleep 100\n4026532602 mnt         3  7710 alice   /usr/bin/podman run --rm busybox sleep 100\n\n4026532603 net         1  7712 alice   sleep 100\n4026532604 net         2  8120 bob     /usr/bin/qemu-system-x86_64 -name guest=vm1 -S\n4026531840 net        37     1 root    /usr/lib/systemd/systemd --switched-root --system\n"], "expected": [{"__tuple__": ["mnt", 1, 3]}, {"__tuple__": ["net", 3, 40]}, {"__tuple__": ["user", 2, 43]}]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 7, 'la7-shared-namespaces', 1, 'func', 'Общие пространства двух процессов', 'Даны два текста — вывод ls -l /proc/PID/ns для двух процессов. Строка ссылки выглядит как «lrwxrwxrwx 1 root root 0 Nov  3 10:15 net -> ''net:[4026531840]''»; кавычки вокруг цели могут быть, а могут отсутствовать. Строки без « -> » (например, «total 0») пропускайте. Имя записи — последнее слово перед « -> », цель — всё после « -> » без пробелов и одинарных кавычек. Напишите функцию shared_namespaces(a, b): верните отсортированный список имён, которые есть в обоих текстах и у которых цели совпадают (pid_for_children и time_for_children — отдельные имена).', 'def shared_namespaces(a, b):
    pass
', 'Разберите каждый текст в словарь имя -> цель, затем пересеките ключи.', '{"func": "shared_namespaces", "tests": [{"args": ["total 0\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 cgroup -> ''cgroup:[4026531835]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 ipc -> ''ipc:[4026531839]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 mnt -> ''mnt:[4026531841]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 net -> ''net:[4026531840]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 pid -> ''pid:[4026531836]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 pid_for_children -> ''pid:[4026531836]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 time -> ''time:[4026531834]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 time_for_children -> ''time:[4026531834]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 user -> ''user:[4026531837]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 uts -> ''uts:[4026531838]''\n", "total 0\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 cgroup -> ''cgroup:[4026531835]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 ipc -> ''ipc:[4026531839]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 mnt -> ''mnt:[4026531841]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 net -> ''net:[4026531840]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 pid -> ''pid:[4026531836]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 pid_for_children -> ''pid:[4026531836]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 time -> ''time:[4026531834]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 time_for_children -> ''time:[4026531834]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 user -> ''user:[4026531837]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 uts -> ''uts:[4026531838]''\n"], "expected": ["cgroup", "ipc", "mnt", "net", "pid", "pid_for_children", "time", "time_for_children", "user", "uts"]}, {"args": ["total 0\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 cgroup -> ''cgroup:[4026531835]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 ipc -> ''ipc:[4026531839]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 mnt -> ''mnt:[4026531841]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 net -> ''net:[4026531840]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 pid -> ''pid:[4026531836]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 pid_for_children -> ''pid:[4026531836]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 time -> ''time:[4026531834]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 time_for_children -> ''time:[4026531834]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 user -> ''user:[4026531837]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 uts -> ''uts:[4026531838]''\n", "total 0\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 cgroup -> ''cgroup:[4026532516]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 ipc -> ''ipc:[4026532514]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 mnt -> ''mnt:[4026532512]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 net -> ''net:[4026532517]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 pid -> ''pid:[4026532515]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 pid_for_children -> ''pid:[4026532515]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 time -> ''time:[4026531834]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 time_for_children -> ''time:[4026531834]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 user -> ''user:[4026531837]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 uts -> ''uts:[4026532513]''\n"], "expected": ["time", "time_for_children", "user"]}, {"args": ["total 0\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 cgroup -> cgroup:[4026532516]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 ipc -> ipc:[4026532514]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 mnt -> mnt:[4026532512]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 net -> net:[4026532517]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 pid -> pid:[4026532515]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 pid_for_children -> pid:[4026532515]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 time -> time:[4026531834]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 time_for_children -> time:[4026531834]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 user -> user:[4026531837]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 uts -> uts:[4026532513]\n", "total 0\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 cgroup -> ''cgroup:[4026531835]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 ipc -> ''ipc:[4026531839]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 mnt -> ''mnt:[4026531841]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 net -> ''net:[4026532517]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 pid -> ''pid:[4026531836]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 pid_for_children -> ''pid:[4026531836]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 time -> ''time:[4026531834]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 time_for_children -> ''time:[4026531834]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 user -> ''user:[4026531837]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 uts -> ''uts:[4026531838]''\n"], "expected": ["net", "time", "time_for_children", "user"]}, {"args": ["total 0\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 cgroup -> ''cgroup:[4026531835]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 ipc -> ''ipc:[4026531839]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 mnt -> ''mnt:[4026531841]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 net -> ''net:[4026531840]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 pid -> ''pid:[4026531836]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 pid_for_children -> ''pid:[4026531836]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 time -> ''time:[4026531834]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 time_for_children -> ''time:[4026531834]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 user -> ''user:[4026531837]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 uts -> ''uts:[4026531838]''\n", "total 0\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 cgroup -> cgroup:[4026533010]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 ipc -> ipc:[4026533011]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 mnt -> mnt:[4026533012]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 net -> net:[4026533013]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 pid -> pid:[4026533014]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 pid_for_children -> pid:[4026533015]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 time -> time:[4026533016]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 time_for_children -> time:[4026533017]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 user -> user:[4026533018]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 uts -> uts:[4026533019]\n"], "expected": []}, {"args": ["total 0\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 cgroup -> ''cgroup:[4026531835]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 ipc -> ''ipc:[4026531839]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 mnt -> ''mnt:[4026531841]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 net -> ''net:[4026532517]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 pid -> ''pid:[4026531836]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 pid_for_children -> ''pid:[4026531836]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 time -> ''time:[4026531834]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 time_for_children -> ''time:[4026531834]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 user -> ''user:[4026531837]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 uts -> ''uts:[4026531838]''\n", "total 0\n"], "expected": []}, {"args": ["total 0\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 net -> ''net:[1]''\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 uts -> ''uts:[2]''\n", "total 0\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 mnt -> mnt:[4]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 net -> net:[1]\nlrwxrwxrwx 1 root root 0 Nov  3 10:15 uts -> uts:[3]\n"], "expected": ["net"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 7, 'la7-translate-id', 2, 'func', 'Перевод номера через uid_map', 'Файл uid_map (или gid_map) — строки из трёх чисел: «внутри снаружи длина»; числа разделены пробелами любой ширины. Строка описывает диапазоны [внутри, внутри+длина) и [снаружи, снаружи+длина), сдвиг в них одинаков. Напишите функцию translate_id(map_text, ident, direction). При direction = "in2out" верните номер снаружи для номера ident внутри пространства, а если внутри он не описан картой, верните -1. При direction = "out2in" верните номер внутри для номера ident снаружи, а если снаружи он не описан картой, верните 65534 (так процесс видит неописанный номер по умолчанию).', 'def translate_id(map_text, ident, direction):
    pass
', 'В каждой строке проверьте a <= ident < a + n (или b <= ident < b + n) и прибавьте разность.', '{"func": "translate_id", "tests": [{"args": ["         0     100000      65536\n", 5, "in2out"], "expected": 100005}, {"args": ["         0     100000      65536\n", 65535, "in2out"], "expected": 165535}, {"args": ["         0     100000      65536\n", 65536, "in2out"], "expected": -1}, {"args": ["         0     100000      65536\n", 100005, "out2in"], "expected": 5}, {"args": ["         0     100000      65536\n", 99999, "out2in"], "expected": 65534}, {"args": ["         0       1000          1\n         1     100000      65536\n", 1, "in2out"], "expected": 100000}, {"args": ["         0       1000          1\n         1     100000      65536\n", 1000, "out2in"], "expected": 0}, {"args": ["         0       1000          1\n         1     100000      65536\n", 165535, "out2in"], "expected": 65536}, {"args": ["         0          0 4294967295\n", 4242, "in2out"], "expected": 4242}, {"args": ["         0       5000        100\n      1000       9000         50\n", 1049, "in2out"], "expected": 9049}, {"args": ["         0       5000        100\n      1000       9000         50\n", 5099, "out2in"], "expected": 99}, {"args": ["         0       5000        100\n      1000       9000         50\n", 5100, "out2in"], "expected": 65534}, {"args": ["", 0, "in2out"], "expected": -1}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 7, 'la7-validate-map', 3, 'func', 'Допустима ли запись в uid_map', 'Моделируем запись в /proc/PID/uid_map или gid_map. Аргументы: map_text — записываемый текст; writer — словарь {"privileged": bool, "euid": число, "kind": "uid" или "gid", "setgroups_deny": bool, "written": bool}; parent — список пар [начало, длина] номеров, существующих в родительском пространстве. Напишите функцию validate_map(map_text, writer, parent): верните "ok", "EINVAL" или "EPERM". Проверки по порядку: 1) written истинно — "EPERM" (карту пишут один раз); 2) нет ни одной строки, строк больше 340, строка не из трёх неотрицательных целых чисел, длина меньше 1, пересекаются диапазоны внутри или диапазоны снаружи — "EINVAL"; 3) диапазон снаружи не помещается целиком в один диапазон из parent — "EPERM"; 4) если писатель не привилегирован (нет CAP_SETUID/CAP_SETGID в родителе): строка должна быть ровно одна, длиной 1, с номером снаружи, равным euid писателя, а для kind = "gid" должно быть setgroups_deny — иначе "EPERM". Иначе "ok".', 'def validate_map(map_text, writer, parent):
    pass
', 'Сначала разберите строки в тройки, затем проверяйте по порядку; для пересечений отсортируйте диапазоны по началу.', '{"func": "validate_map", "tests": [{"args": ["0 1000 1\n", {"privileged": false, "euid": 1000, "kind": "uid", "setgroups_deny": false, "written": false}, [[0, 4294967295]]], "expected": "ok"}, {"args": ["0 1000 1\n", {"privileged": false, "euid": 1000, "kind": "gid", "setgroups_deny": false, "written": false}, [[0, 4294967295]]], "expected": "EPERM"}, {"args": ["0 1000 1\n", {"privileged": false, "euid": 1000, "kind": "gid", "setgroups_deny": true, "written": false}, [[0, 4294967295]]], "expected": "ok"}, {"args": ["0 1001 1\n", {"privileged": false, "euid": 1000, "kind": "uid", "setgroups_deny": true, "written": false}, [[0, 4294967295]]], "expected": "EPERM"}, {"args": ["0 1000 2\n", {"privileged": false, "euid": 1000, "kind": "uid", "setgroups_deny": true, "written": false}, [[0, 4294967295]]], "expected": "EPERM"}, {"args": ["0 1000 1\n1 100000 65536\n", {"privileged": true, "euid": 0, "kind": "uid", "setgroups_deny": false, "written": false}, [[0, 4294967295]]], "expected": "ok"}, {"args": ["0 1000 1\n1 100000 65536\n", {"privileged": false, "euid": 1000, "kind": "uid", "setgroups_deny": true, "written": false}, [[0, 4294967295]]], "expected": "EPERM"}, {"args": ["0 100000 65536\n", {"privileged": true, "euid": 0, "kind": "uid", "setgroups_deny": false, "written": true}, [[0, 4294967295]]], "expected": "EPERM"}, {"args": ["", {"privileged": true, "euid": 0, "kind": "uid", "setgroups_deny": false, "written": false}, [[0, 4294967295]]], "expected": "EINVAL"}, {"args": ["0 100000 0\n", {"privileged": true, "euid": 0, "kind": "uid", "setgroups_deny": false, "written": false}, [[0, 4294967295]]], "expected": "EINVAL"}, {"args": ["0 100000 10\n5 200000 10\n", {"privileged": true, "euid": 0, "kind": "uid", "setgroups_deny": false, "written": false}, [[0, 4294967295]]], "expected": "EINVAL"}, {"args": ["0 100000 10\n20 100005 10\n", {"privileged": true, "euid": 0, "kind": "uid", "setgroups_deny": false, "written": false}, [[0, 4294967295]]], "expected": "EINVAL"}, {"args": ["0 100000 abc\n", {"privileged": true, "euid": 0, "kind": "uid", "setgroups_deny": false, "written": false}, [[0, 4294967295]]], "expected": "EINVAL"}, {"args": ["0 100000 65536\n", {"privileged": true, "euid": 0, "kind": "uid", "setgroups_deny": false, "written": false}, [[0, 1000], [100000, 65536]]], "expected": "ok"}, {"args": ["0 99999 65536\n", {"privileged": true, "euid": 0, "kind": "uid", "setgroups_deny": false, "written": false}, [[0, 1000], [100000, 65536]]], "expected": "EPERM"}, {"args": ["0 1000 1\n1 1001 1\n2 1002 1\n3 1003 1\n4 1004 1\n5 1005 1\n6 1006 1\n7 1007 1\n8 1008 1\n9 1009 1\n10 1010 1\n11 1011 1\n12 1012 1\n13 1013 1\n14 1014 1\n15 1015 1\n16 1016 1\n17 1017 1\n18 1018 1\n19 1019 1\n20 1020 1\n21 1021 1\n22 1022 1\n23 1023 1\n24 1024 1\n25 1025 1\n26 1026 1\n27 1027 1\n28 1028 1\n29 1029 1\n30 1030 1\n31 1031 1\n32 1032 1\n33 1033 1\n34 1034 1\n35 1035 1\n36 1036 1\n37 1037 1\n38 1038 1\n39 1039 1\n40 1040 1\n41 1041 1\n42 1042 1\n43 1043 1\n44 1044 1\n45 1045 1\n46 1046 1\n47 1047 1\n48 1048 1\n49 1049 1\n50 1050 1\n51 1051 1\n52 1052 1\n53 1053 1\n54 1054 1\n55 1055 1\n56 1056 1\n57 1057 1\n58 1058 1\n59 1059 1\n60 1060 1\n61 1061 1\n62 1062 1\n63 1063 1\n64 1064 1\n65 1065 1\n66 1066 1\n67 1067 1\n68 1068 1\n69 1069 1\n70 1070 1\n71 1071 1\n72 1072 1\n73 1073 1\n74 1074 1\n75 1075 1\n76 1076 1\n77 1077 1\n78 1078 1\n79 1079 1\n80 1080 1\n81 1081 1\n82 1082 1\n83 1083 1\n84 1084 1\n85 1085 1\n86 1086 1\n87 1087 1\n88 1088 1\n89 1089 1\n90 1090 1\n91 1091 1\n92 1092 1\n93 1093 1\n94 1094 1\n95 1095 1\n96 1096 1\n97 1097 1\n98 1098 1\n99 1099 1\n100 1100 1\n101 1101 1\n102 1102 1\n103 1103 1\n104 1104 1\n105 1105 1\n106 1106 1\n107 1107 1\n108 1108 1\n109 1109 1\n110 1110 1\n111 1111 1\n112 1112 1\n113 1113 1\n114 1114 1\n115 1115 1\n116 1116 1\n117 1117 1\n118 1118 1\n119 1119 1\n120 1120 1\n121 1121 1\n122 1122 1\n