INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 7, 'la7-netns-ids', 4, 'func', 'Идентификаторы в ip netns list', 'Вывод ip netns list — по строке на пространство: «имя» или «имя (id: N)», если у пространства есть идентификатор N. Напишите функцию netns_ids(text): верните словарь имя → идентификатор для всех пространств. Тем, у кого идентификатора нет, присвойте его так, как это делает «ip netns set имя auto» в нашей модели: по порядку строк, каждому наименьший неотрицательный номер, который ещё не занят (занятые — те, что указаны в тексте, и уже присвоенные). Пустые строки пропускайте, пробелы по краям строки игнорируйте.', 'def netns_ids(text):
    pass
', 'Сначала соберите занятые номера из всего текста, потом пройдите строки без номера по порядку.', '{"func": "netns_ids", "tests": [{"args": ["blue (id: 1)\nred (id: 0)\ntest\n"], "expected": {"blue": 1, "red": 0, "test": 2}}, {"args": [""], "expected": {}}, {"args": ["a\nb\nc\n"], "expected": {"a": 0, "b": 1, "c": 2}}, {"args": ["a (id: 0)\nb (id: 2)\nc\nd\ne\n"], "expected": {"a": 0, "b": 2, "c": 1, "d": 3, "e": 4}}, {"args": ["  web (id: 5)  \n\n   db\n"], "expected": {"web": 5, "db": 0}}, {"args": ["x (id: 10)\n"], "expected": {"x": 10}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 7, 'la7-runtime-ns', 5, 'func', 'Пространства контейнера по ключам', 'Docker-подобный рантайм получает список аргументов команды run. Напишите функцию runtime_ns(args, userns_remap): верните словарь с ключами "mnt", "pid", "net", "uts", "ipc", "user"; значение — "new" (у контейнера своё пространство), "host" (общее с хостом) или "container:ИМЯ" (общее с другим контейнером, строка в точности как в аргументе). Правила. mnt всегда "new". Ключи --pid, --uts, --ipc, --network (и его синоним --net) принимают значение как через =, так и следующим аргументом: "--pid=host" или "--pid", "host". Значение "host" даёт "host"; для pid, ipc и net значение, начинающееся с "container:", даёт его целиком; всё остальное (в том числе отсутствие ключа, bridge, none, private, имя пользовательской сети) даёт "new". Для user: "--userns=host" (или "--userns", "host") даёт "host"; без него — "new", если демон запущен с переназначением пользователей (userns_remap истинно), и "host" иначе. Если ключ повторён, действует последний. Остальные аргументы (--name, -p, --hostname, --privileged, образ и их значения) игнорируйте.', 'def runtime_ns(args, userns_remap):
    pass
', 'Пройдите список по индексу: если аргумент равен ключу, значение — следующий; если начинается с «ключ=», значение после знака.', '{"func": "runtime_ns", "tests": [{"args": [["-d", "--name", "web", "-p", "8080:80", "nginx"], false], "expected": {"mnt": "new", "pid": "new", "net": "new", "uts": "new", "ipc": "new", "user": "host"}}, {"args": [["--pid=host", "--network=host", "alpine"], false], "expected": {"mnt": "new", "pid": "host", "net": "host", "uts": "new", "ipc": "new", "user": "host"}}, {"args": [["--pid", "host", "--net", "host", "--uts", "host", "--ipc", "host", "alpine"], false], "expected": {"mnt": "new", "pid": "host", "net": "host", "uts": "host", "ipc": "host", "user": "host"}}, {"args": [["--network", "container:web", "--ipc=container:web", "curlimages/curl"], false], "expected": {"mnt": "new", "pid": "new", "net": "container:web", "uts": "new", "ipc": "container:web", "user": "host"}}, {"args": [["--network=none", "--hostname", "host", "--privileged", "busybox"], false], "expected": {"mnt": "new", "pid": "new", "net": "new", "uts": "new", "ipc": "new", "user": "host"}}, {"args": [["--network=host", "--network=mynet", "busybox"], true], "expected": {"mnt": "new", "pid": "new", "net": "new", "uts": "new", "ipc": "new", "user": "new"}}, {"args": [["--userns=host", "--pid=container:db"], true], "expected": {"mnt": "new", "pid": "container:db", "net": "new", "uts": "new", "ipc": "new", "user": "host"}}, {"args": [["--name", "host", "--pid=private", "x"], false], "expected": {"mnt": "new", "pid": "new", "net": "new", "uts": "new", "ipc": "new", "user": "host"}}, {"args": [[], true], "expected": {"mnt": "new", "pid": "new", "net": "new", "uts": "new", "ipc": "new", "user": "new"}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 7, 'la7-unshare-flags', 6, 'func', 'Флаги unshare под задачу', 'Подберите флаги ан-шер. Функция unshare_flags(want, proc, root, privileged): want — список нужных пространств из "mnt", "uts", "ipc", "net", "pid", "cgroup", "time", "user"; proc — нужен ли свежий /proc; root — нужно ли быть рутом внутри (без прав рута снаружи); privileged — запускает ли команду рут. Верните отсортированный список уникальных длинных флагов. Соответствие: mnt → --mount, uts → --uts, ipc → --ipc, net → --net, pid → --pid, cgroup → --cgroup, time → --time, user → --user. Правила: для pid добавляется --fork; proc добавляет --mount-proc и убирает --mount (он подразумевается); root заменяет --user на --map-root-user (он подразумевает пользовательское пространство); непривилегированному запуску, если нужно хоть одно пространство кроме user или свежий /proc, добавляется --user (если не включён --map-root-user).', 'def unshare_flags(want, proc, root, privileged):
    pass
', 'Соберите множество флагов, затем примените правила по очереди; в конце sorted().', '{"func": "unshare_flags", "tests": [{"args": [["net"], false, false, true], "expected": ["--net"]}, {"args": [["pid", "mnt"], true, false, true], "expected": ["--fork", "--mount-proc", "--pid"]}, {"args": [["pid"], true, false, false], "expected": ["--fork", "--mount-proc", "--pid", "--user"]}, {"args": [["net", "uts"], false, true, false], "expected": ["--map-root-user", "--net", "--uts"]}, {"args": [[], false, true, false], "expected": ["--map-root-user"]}, {"args": [["user"], false, false, false], "expected": ["--user"]}, {"args": [[], false, false, false], "expected": []}, {"args": [["mnt"], false, false, false], "expected": ["--mount", "--user"]}, {"args": [["time", "cgroup", "ipc"], false, false, true], "expected": ["--cgroup", "--ipc", "--time"]}, {"args": [[], true, false, true], "expected": ["--mount-proc"]}, {"args": [["user", "pid"], true, true, true], "expected": ["--fork", "--map-root-user", "--mount-proc", "--pid"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 7, 'la7-nspid-map', 7, 'func', 'PID на хосте и внутри контейнера', 'Дан список текстов — фрагментов /proc/PID/status разных процессов, как их видит хост. В каждом есть строка «NSpid:» с номерами процесса во всех PID-пространствах, в которых он состоит: первое число — номер на хосте, последнее — номер во внутреннем пространстве, числа разделены табуляциями или пробелами. Остальные строки (Name:, Pid:, NStgid: и т. д.) не нужны; строки NStgid, NSpgid, NSsid с похожим началом не считаются. Напишите функцию pid_pairs(statuses): верните список кортежей (номер_на_хосте, номер_внутри), только для процессов, у которых в NSpid не меньше двух чисел (то есть которые живут во вложенном пространстве), отсортированный по номеру на хосте. Тексты без строки NSpid пропускайте.', 'def pid_pairs(statuses):
    pass
', 'Ищите строку, начинающуюся ровно с «NSpid:», разбейте остаток split() и возьмите первый и последний элементы.', '{"func": "pid_pairs", "tests": [{"args": [["Name:\tnginx\nState:\tS (sleeping)\nTgid:\t3801\nPid:\t3801\nPPid:\t1\nNStgid:\t3801\t1\nNSpid:\t3801\t1\nNSpgid:\t3801\t1\nNSsid:\t3801\t1\n", "Name:\tnginx\nState:\tS (sleeping)\nTgid:\t3830\nPid:\t3830\nPPid:\t1\nNStgid:\t3830\t7\nNSpid:\t3830\t7\nNSpgid:\t3830\t7\nNSsid:\t3830\t7\n", "Name:\tsshd\nUmask:\t0022\nState:\tS (sleeping)\nTgid:\t812\nNgid:\t0\nPid:\t812\nPPid:\t1\nNStgid:\t812\nNSpid:\t812\nNSpgid:\t812\nNSsid:\t812\n"]], "expected": [{"__tuple__": [3801, 1]}, {"__tuple__": [3830, 7]}]}, {"args": [[]], "expected": []}, {"args": [["Name:\tsshd\nUmask:\t0022\nState:\tS (sleeping)\nTgid:\t812\nNgid:\t0\nPid:\t812\nPPid:\t1\nNStgid:\t812\nNSpid:\t812\nNSpgid:\t812\nNSsid:\t812\n"]], "expected": []}, {"args": [["Name:\tsleep\nState:\tS (sleeping)\nTgid:\t9000\nPid:\t9000\nPPid:\t1\nNStgid:\t9000\t120\t5\t1\nNSpid:\t9000\t120\t5\t1\nNSpgid:\t9000\t120\t5\t1\nNSsid:\t9000\t120\t5\t1\n", "Name:\tbash\nState:\tS (sleeping)\nTgid:\t8000\nPid:\t8000\nPPid:\t1\nNStgid:\t8000\t100\t1\nNSpid:\t8000\t100\t1\nNSpgid:\t8000\t100\t1\nNSsid:\t8000\t100\t1\n"]], "expected": [{"__tuple__": [8000, 1]}, {"__tuple__": [9000, 1]}]}, {"args": [["Name:\tinit\nPid:\t1\n"]], "expected": []}, {"args": [["Name:\tapp\nState:\tS (sleeping)\nTgid:\t2200\nPid:\t2200\nPPid:\t1\nNStgid:\t2200\t44\nNSpid:\t2200\t44\nNSpgid:\t2200\t44\nNSsid:\t2200\t44\n", "Name:\tapp\nState:\tS (sleeping)\nTgid:\t2100\nPid:\t2100\nPPid:\t1\nNStgid:\t2100\t12\nNSpid:\t2100\t12\nNSpgid:\t2100\t12\nNSsid:\t2100\t12\n"]], "expected": [{"__tuple__": [2100, 12]}, {"__tuple__": [2200, 44]}]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 7, 'la7-timens-clock', 8, 'func', 'Часы во временном пространстве', 'Файл /proc/PID/timens_offsets состоит из строк «часы секунды наносекунды», где часы — monotonic или boottime; секунды могут быть отрицательными, наносекунды неотрицательны. Показание часов внутри пространства в нашей модели равно показанию хоста плюс смещение (секунды·10^9 + наносекунды). Часы realtime не виртуализируются: внутри показание то же, что на хосте. Если в файле часов нет, смещение 0. Напишите функцию timens_clock(offsets_text, clock, host_ns): clock — monotonic, boottime или realtime, host_ns — показание хоста в наносекундах; верните показание внутри пространства в наносекундах или -1, если результат был бы отрицательным.', 'def timens_clock(offsets_text, clock, host_ns):
    pass
', 'Разберите строки в словарь часы -> (сек, нс), затем host_ns + сек*10**9 + нс.', '{"func": "timens_clock", "tests": [{"args": ["monotonic           86400         0\nboottime          172800         0\n", "monotonic", 5000000000], "expected": 86405000000000}, {"args": ["monotonic           86400         0\nboottime          172800         0\n", "boottime", 0], "expected": 172800000000000}, {"args": ["monotonic           86400         0\nboottime          172800         0\n", "realtime", 1762160000000000000], "expected": 1762160000000000000}, {"args": ["monotonic              -10 500000000\n", "monotonic", 20000000000], "expected": 10500000000}, {"args": ["monotonic              -10         0\n", "monotonic", 9000000000], "expected": -1}, {"args": ["", "boottime", 42], "expected": 42}, {"args": ["boottime 1 1\n", "monotonic", 7], "expected": 7}]}');
